-- Migration 035: Institutions juridictionnelles - Ch1

SELECT s.id, 'IJ — Introduction à la justice', 'Chapitre 1 - Introduction à la justice', 'facile',
  '[{"question":"Qu''est-ce que la justice ?","choices":["A. L''armée","B. Fonction rendre justice et trancher litiges","C. La police","D. L''exécutif"],"correct_index":1,"explanation":"Justice : fonction rendre décisions et trancher conflits selon loi."},{"question":"Quels sont trois ordres de juridiction en France ?","choices":["A. Civile, pénale, administrative","B. Nationale, régionale, locale","C. Judiciaire, administratif, constitutionnel","D. Premiers juges, appels, Cassation"],"correct_index":2,"explanation":"Trois ordres : judiciaire (civil/pénal), administratif, constitutionnel."},{"question":"Qu''est-ce que l''ordre judiciaire ?","choices":["A. Branche gouvernement","B. Ensemble juridictions litiges civils et pénaux","C. Tribunaux militaires","D. Administration justice"],"correct_index":1,"explanation":"Ordre judiciaire : tous tribunaux civils et pénaux."},{"question":"Qu''est-ce que l''ordre administratif ?","choices":["A. Administration gouvernementale","B. Ensemble juridictions litiges administratifs","C. Le Parlement","D. Les mairies"],"correct_index":1,"explanation":"Ordre administratif : tribunaux administratifs et Cour administrative suprême."},{"question":"Quel est rôle d''un juge ?","choices":["A. Gouverner pays","B. Appliquer loi et rendre justice","C. Faire loi","D. Administrer État"],"correct_index":1,"explanation":"Juge : applique loi, tranche litiges, rend décisions obligatoires."},{"question":"Qu''est-ce que l''indépendance de magistrature ?","choices":["A. Juges n''obéissent à personne","B. Juges ne dépendent que de loi","C. Juges ne paient pas impôts","D. Juges changent chaque année"],"correct_index":1,"explanation":"Indépendance magistrature : juges n''obéissent qu''à loi."},{"question":"Comment l''indépendance est-elle garantie ?","choices":["A. Par police","B. Inamovibilité, indépendance financière et statutaire","C. Par droits électoraux","D. Par constitutions"],"correct_index":1,"explanation":"Garanties : inamovibilité, indépendance budgétaire, statut."},{"question":"Qu''est-ce qu''un tribunal de première instance ?","choices":["A. Tribunal d''appel","B. Tribunal traitant litiges sans appel préalable","C. Cour de cassation","D. Tribunal arbitral"],"correct_index":1,"explanation":"Tribunal première instance : juge les affaires en premier."},{"question":"Qu''est-ce qu''une cour d''appel ?","choices":["A. Tribunal première instance","B. Juridiction réexamine décisions en appel","C. Cour de cassation","D. Tribunal arbitral"],"correct_index":1,"explanation":"Cour appel : réexamine appels, confirme ou infirme décisions."},{"question":"Qu''est-ce que Cour de cassation ?","choices":["A. Cour appel","B. Juridiction suprême ordre judiciaire","C. Tribunal première instance","D. Cour internationale"],"correct_index":1,"explanation":"Cour cassation : vérifie respect loi par juridictions inférieures."},{"question":"Quel est rôle parquet dans justice pénale ?","choices":["A. Juger accusés","B. Représenter État et poursuivre infractions","C. Défendre accusés","D. Organiser tribunal"],"correct_index":1,"explanation":"Parquet (ministère public) : représente société, engage poursuites pénales."},{"question":"Qu''est-ce qu''un tribunal correctionnel ?","choices":["A. Tribunal civil","B. Tribunal pénal pour délits","C. Tribunal pour crimes","D. Tribunal administratif"],"correct_index":1,"explanation":"Tribunal correctionnel : juge délits (infractions entre contraventions crimes)."},{"question":"Qu''est-ce qu''une cour d''assises ?","choices":["A. Tribunal civil","B. Tribunal jugeant crimes avec jury","C. Tribunal administratif","D. Cour appel"],"correct_index":1,"explanation":"Cour assises : juge crimes graves avec jury populaire."},{"question":"Qu''est-ce qu''une juridiction civile ?","choices":["A. Tribunal pénal","B. Juridiction traitant litiges droit civil","C. Tribunal administratif","D. Tribunal international"],"correct_index":1,"explanation":"Juridiction civile : règle conflits entre particuliers."},{"question":"Qu''est-ce qu''une juridiction pénale ?","choices":["A. Tribunal civil","B. Juridiction jugeant infractions pénales","C. Tribunal administratif","D. Tribunal commercial"],"correct_index":1,"explanation":"Juridiction pénale : juge crimes, délits, contraventions."},{"question":"Quel est principe d''impartialité ?","choices":["A. Juges favorisent gouvernement","B. Juges tranchent sans parti pris","C. Juges tous même parti","D. Juges suivent majorité"],"correct_index":1,"explanation":"Impartialité : juge neutre, ne favorise aucune partie."},{"question":"Quel est rôle de l''avocat ?","choices":["A. Juger affaires","B. Représenter et défendre clients justice","C. Poursuivre infractions","D. Administrer tribunaux"],"correct_index":1,"explanation":"Avocat : défend droits et intérêts clients devant juge."},{"question":"Qu''est-ce que l''accès à la justice ?","choices":["A. Droit être juge","B. Droit saisir tribunaux défendre droits","C. Entrée palais de justice","D. Obligation comparaître"],"correct_index":1,"explanation":"Accès justice : droit reconnu à tout citoyen soumettre litiges."},{"question":"Qu''est-ce que droit à procès équitable ?","choices":["A. Droit acquittement","B. Droit jugé impartialement avec droits défense","C. Droit pas jugé","D. Droit changer juge"],"correct_index":1,"explanation":"Droit procès équitable : procédure juste avec garanties légales."}]'::jsonb
FROM public.subjects s
WHERE s.slug = 'institutions-juridictionnelles'
AND NOT EXISTS (SELECT 1 FROM public.quizzes q WHERE q.subject_id = s.id AND q.chapter = 'Chapitre 1 - Introduction à la justice');




