INSERT INTO public.flashcards (subject_id, deck_name, front, back) SELECT s.id, 'IJ Ch1', 'Justice', 'Fonction rendre justice et trancher litiges' FROM public.subjects s WHERE s.slug = 'institutions-juridictionnelles' AND NOT EXISTS (SELECT 1 FROM public.flashcards f WHERE f.subject_id = s.id AND f.front = 'Justice');
