INSERT INTO public.exercises (subject_id, title, type, difficulty, statement, correction) SELECT s.id, 'IJ Ch1 Ex1', 'dissertation', 'moyen', 'Pourquoi l''indépendance judiciaire est-elle essentielle ?', 'Si juges dépendent gouvernement, ne peuvent rendre décisions justes. Droits fondamentaux pas protégés. État pourrait réprimer opposants politiques. Indépendance garantit État droit et protection arbitraire.' FROM public.subjects s WHERE s.slug = 'institutions-juridictionnelles' AND NOT EXISTS (SELECT 1 FROM public.exercises e WHERE e.subject_id = s.id AND e.title = 'IJ Ch1 Ex1');
INSERT INTO public.exercises (subject_id, title, type, difficulty, statement, correction) SELECT s.id, 'IJ Ch1 Ex2', 'dissertation', 'moyen', 'Quel intérêt du principe de double degré de juridiction ?', 'Double degré (jugement + appel) réexamine décisions. Protège erreurs juges 1ère instance. Corrige injustices manifestes. Renforce qualité. Allonge procès mais renforce confiance justice.' FROM public.subjects s WHERE s.slug = 'institutions-juridictionnelles' AND NOT EXISTS (SELECT 1 FROM public.exercises e WHERE e.subject_id = s.id AND e.title = 'IJ Ch1 Ex2');
INSERT INTO public.exercises (subject_id, title, type, difficulty, statement, correction) SELECT s.id, 'IJ Ch1 Ex3', 'dissertation', 'difficile', 'L''accès à la justice doit-il être gratuit ?', 'Gratuité : principe démocratique, droit égal, protège pauvres. Inconvénients : coûts massifs, accès massif engorg tribunaux. Compromis français : aide juridictionnelle indigents. Accès garanti mais modulé selon ressources.' FROM public.subjects s WHERE s.slug = 'institutions-juridictionnelles' AND NOT EXISTS (SELECT 1 FROM public.exercises e WHERE e.subject_id = s.id AND e.title = 'IJ Ch1 Ex3');
